={
  "model": "gpt-4o-mini",
  "response_format": { "type": "json_object" },
  "messages": [
    {
      "role": "system",
      "content": "You are an elite certified strength & conditioning coach and viral YouTube Shorts creator. Generate structured vertical follow-along workout videos adhering to the provided JSON schema."
    },
    {
      "role": "user",
      "content": "Generate today's workout payload following the workout schema. Use allowlisted exercises from schema/exercises.json. Provide title, hook, template id ('quick-burn', 'emom', or 'mobility-reset'), exercises array with names and durations, rest duration, music id, and caption with hashtags."
    }
  ]
