parameters.jsCode:
const response = $input.item.json;
let rawContent = response.choices?.[0]?.message?.content;
if (!rawContent) {
  throw new Error('LiteLLM returned empty or malformed completion');
}

let workout;
try {
  workout = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
} catch (err) {
  throw new Error('Failed to parse LLM JSON: ' + err.message);
}

// Core schema validation
const validTemplates = ['quick-burn', 'emom', 'mobility-reset'];
if (!validTemplates.includes(workout.template_id)) {
  workout.template_id = 'quick-burn';
}

if (!workout.title) workout.title = 'Daily Quick Burn Workout';
if (!Array.isArray(workout.exercises) || workout.exercises.length === 0) {
  throw new Error('Workout payload must contain a non-empty exercises array');
}

return {
  json: {
    status: 'scripted',
    template_id: workout.template_id,
    title: workout.title,
    scheduled_date: new Date().toISOString().split('T')[0],
    payload: JSON.stringify(workout),
    created_at: new Date().toISOString()
  }
};
